#!/usr/bin/env python3
import sys, os, json, csv, gzip, io, re
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
_zc = {}
def Z(name):
    if name not in _zc:
        _zc[name] = ZoneInfo(name)
    return _zc[name]

def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8')
    if t.startswith('\ufeff'):
        t = t[1:]
    return t

def lines_of(t):
    return [l for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']

def epoch_of_local(naive, zone, dst_hint=None):
    """naive datetime in zone -> epoch seconds. dst_hint: True/False picks among repeated times;
    None picks first occurrence."""
    z = Z(zone)
    a = naive.replace(tzinfo=z, fold=0)
    b = naive.replace(tzinfo=z, fold=1)
    if a.utcoffset() != b.utcoffset():
        # ambiguous or gap
        if dst_hint is None:
            pick = a
        else:
            cands = [x for x in (a, b) if bool(x.dst()) == dst_hint]
            pick = cands[0] if cands else a
    else:
        pick = a
    return int(pick.timestamp())

def std_offset(zone):
    z = Z(zone)
    for m in (1, 7):
        d = datetime(2026, m, 1, tzinfo=z)
        if not d.dst():
            return d.utcoffset()
    d = datetime(2026, 1, 1, tzinfo=z)
    return d.utcoffset() - d.dst()

def read_header_csv_rows(lines, required):
    """yield dict rows, honoring repeated header rows."""
    hdr = None
    for row in csv.reader(lines):
        if not row:
            continue
        cells = [c.strip() for c in row]
        if all(r in cells for r in required):
            hdr = cells
            continue
        if hdr is None:
            continue
        yield dict(zip(hdr, row))

def parse_abbr(t, site, zone):
    out = []
    for r in read_header_csv_rows(lines_of(t), ('Badge', 'Punch', 'Date', 'Time')):
        d = datetime.strptime(r['Date'].strip(), '%m/%d/%Y')
        tm = r['Time'].strip()
        m = re.fullmatch(r'(\d{1,2}):(\d\d):(\d\d)\s*([AaPp][Mm])?', tm)
        h, mi, s, ap = int(m[1]), int(m[2]), int(m[3]), m[4]
        if ap:
            h = h % 12 + (12 if ap.upper() == 'PM' else 0)
        naive = d.replace(hour=h, minute=mi, second=s)
        ab = (r.get('Zone') or '').strip().upper()
        hint = True if ab.endswith('DT') else False if ab.endswith('ST') else None
        out.append((r['Record'].strip(), r['Badge'].strip(), r['Punch'].strip().upper(), epoch_of_local(naive, zone, hint)))
    return out

def parse_epoch(t, site, zone):
    out = []
    schema = 1
    for l in lines_of(t):
        o = json.loads(l)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'heartbeat' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, dr, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
            ts = int(ms // 1000)
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o:
                ts = int(o['ts_ms'] // 1000)
            else:
                ts = int(o['ts'] // 1)
        out.append((str(pid), str(emp).strip(), str(dr).upper(), ts))
    return out

def parse_offset(t, site, zone):
    out = []
    for r in csv.DictReader(lines_of(t), delimiter=';'):
        ev = r['event'].strip().lower()
        dt = datetime.fromisoformat(r['timestamp'].strip())
        out.append((r['punch_id'].strip(), r['employee'].strip(), 'IN' if ev == 'clock_in' else 'OUT', int(dt.timestamp())))
    return out

def parse_legacy(t, site, zone):
    out = []
    default = std_offset(zone)
    off = default
    for l in lines_of(t):
        k = l[0]
        if k == 'H':
            s = l[13:18].strip()
            if s and s[0] in '+-' and len(s) >= 5:
                sec = (int(s[1:3]) * 60 + int(s[3:5])) * 60
                off = timedelta(seconds=-sec if s[0] == '-' else sec)
            else:
                off = default
        elif k == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            dr = 'IN' if l[15] == 'I' else 'OUT'
            dt = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            ts = int((dt.replace(tzinfo=UTC) - off).timestamp())
            out.append((pid, 'E' + badge, dr, ts))
    return out

def parse_de(t, site, zone):
    out = []
    for r in csv.DictReader(lines_of(t), delimiter='\t'):
        d = datetime.strptime(r['Datum'].strip() + ' ' + r['Uhrzeit'].strip(), '%d.%m.%Y %H:%M')
        zn = r['Zeitzone'].strip().upper()
        hint = True if zn == 'MESZ' else False if zn == 'MEZ' else None
        out.append((r['Nr'].strip(), r['Ausweis'].strip(), 'IN' if r['Buchung'].strip().upper() == 'K' else 'OUT',
                    epoch_of_local(d, zone, hint)))
    return out

def parse_localcsv(t, site, zone):
    out = []
    for r in csv.DictReader(lines_of(t)):
        d = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'].strip(), r['employee_id'].strip(), r['direction'].strip().upper(), epoch_of_local(d, zone, None)))
    return out

def parse_localjsonl(t, site, zone):
    out = []
    for l in lines_of(t):
        o = json.loads(l)
        p = o.get('punch') if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        d = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), str(p['badge']).strip(), str(p['type']).strip().upper(), epoch_of_local(d, zone, None)))
    return out

PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}

def read_csv(path):
    return list(csv.DictReader(lines_of(read_text(path))))

def local_dt(ts, zone):
    return datetime.fromtimestamp(ts, Z(zone))

def round_ts(ts, zone):
    off = int(local_dt(ts, zone).utcoffset().total_seconds())
    ls = ts + off
    r = ((ls + 180) // 360) * 360
    return ts + (r - ls)

def night_minutes(a, b, zone):
    if b <= a:
        return 0
    oa = int(local_dt(a, zone).utcoffset().total_seconds())
    ob = int(local_dt(b, zone).utcoffset().total_seconds())
    def overlap(x, y, off):  # x,y epoch; count night seconds using fixed offset
        lx, ly = x + off, y + off
        tot = 0
        d = (lx // 86400) - 1
        while d * 86400 - 7200 < ly:
            s = d * 86400 - 7200
            e = d * 86400 + 21600
            tot += max(0, min(ly, e) - max(lx, s))
            d += 1
        return tot
    if oa == ob:
        return overlap(a, b, oa) // 60
    tot = 0
    t = a
    while t < b:
        n = min(b, t + 60)
        o = int(local_dt(t, zone).utcoffset().total_seconds())
        tot += overlap(t, n, o)
        t = n
    return tot // 60

def main():
    inp, outf = sys.argv[1], sys.argv[2]
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00')).timestamp()
    sites = {r['site'].strip(): (r['timezone'].strip(), r['format'].strip()) for r in read_csv(os.path.join(inp, 'sites.csv'))}
    emps = read_csv(os.path.join(inp, 'employees.csv'))
    emp_home = {r['employee_id'].strip(): r['home_site'].strip() for r in emps}
    rates = {}
    for r in read_csv(os.path.join(inp, 'rates.csv')):
        rates.setdefault(r['employee_id'].strip(), []).append((date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    punches = {}   # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                t = read_text(os.path.join(root, fn))
                for pid, emp, dr, ts in PARSERS[fmt](t, site, zone):
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # corrections
    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for root, _, files in os.walk(cd):
            for fn in files:
                for r in read_csv(os.path.join(root, fn)):
                    corr.append(r)
    for r in corr:
        r['_t'] = datetime.fromisoformat(r['issued_at'].strip().replace('Z', '+00:00')).timestamp()
    corr = [r for r in corr if r['_t'] <= cutoff]
    corr.sort(key=lambda r: (r['_t'], r['correction_id']))
    applied = 0
    for r in corr:
        k = (r['site'].strip(), r['punch_id'].strip())
        act = r['action'].strip().lower()
        if act == 'void':
            if k in punches:
                del punches[k]; applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = int(datetime.fromisoformat(r['time'].strip()).timestamp()); applied += 1
        elif act == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'].strip(), r['type'].strip().upper(),
                              int(datetime.fromisoformat(r['time'].strip()).timestamp())]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emp_home and site in sites:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emp_home}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    def workday(rts, hz):
        return local_dt(rts, hz).date()
    def inperiod(d):
        return pstart <= d <= pend

    for emp, lst in byemp.items():
        hz = sites[emp_home[emp]][0]
        lst.sort()
        kept = []
        for ts, _, site, pid, dr in lst:
            if kept and kept[-1][4] == dr and ts - kept[-1][0] <= 300:
                if inperiod(workday(round_ts(ts, sites[site][0]), hz)):
                    exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))
        # rounded
        kp = [(round_ts(ts, sites[site][0]), dr, site) for ts, _, site, pid, dr in kept]
        shifts = []
        i = 0
        n = len(kp)
        while i < n:
            rts, dr, site = kp[i]
            wd = workday(rts, hz)
            if dr == 'OUT':
                if inperiod(wd): exc['orphan_outs'] += 1
                i += 1
                continue
            if i + 1 < n and kp[i+1][1] == 'OUT' and kp[i+1][0] - rts <= 16 * 3600:
                shifts.append((rts, kp[i+1][0], site, wd))
                i += 2
            else:
                if inperiod(wd): exc['open_shifts'] += 1
                i += 1
        shifts = [s for s in shifts if inperiod(s[3])]
        shifts.sort(key=lambda s: s[0])
        daycum = {}
        weekcum = {}
        R = res[emp]
        for a, b, site, wd in shifts:
            zone = sites[site][0]
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, zone), paid)
            c = daycum.get(wd, 0)
            dot = max(0, c + paid - 480) - max(0, c - 480)
            daycum[wd] = c + paid
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            w = weekcum.get(wk, 0)
            wot = max(0, w + nd - 2400) - max(0, w - 2400)
            weekcum[wk] = w + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(emp, []):
                if ef <= wd: rate = rt
            if rate is None:
                rate = Fraction(0)
            pay = rate * (Fraction(reg) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            R['shifts'] += 1; R['paid_minutes'] += paid; R['overtime_minutes'] += ot
            R['night_minutes'] += night; R['gross'] += pay

    def money(f):
        c = (f * 100 + Fraction(1, 2)).__floor__()
        return f"{c // 100}.{c % 100:02d}"
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    employees = {}
    for e in sorted(res):
        R = res[e]
        g = money(R['gross'])
        totc += int(g.replace('.', ''))
        for k in tot: tot[k] += R[k]
        employees[e] = dict(shifts=R['shifts'], paid_minutes=R['paid_minutes'], overtime_minutes=R['overtime_minutes'],
                            night_minutes=R['night_minutes'], gross=g)
    tot['gross'] = f"{totc // 100}.{totc % 100:02d}"
    out = dict(period=dict(start=period['start'], end=period['end']), employees=employees, exceptions=exc, totals=tot)
    with open(outf, 'w') as f:
        json.dump(out, f, indent=1)

main()
